-- จับได้ทุกช่องทาง (หน้าเว็บ IAM-X, UPM อนุมัติคำร้อง, สคริปต์) · ผู้แก้ = CLIENT_IDENTIFIER ที่แอปตั้ง (ถ้ามี) ไม่งั้น session/module
-- บันทึก audit ล้มต้องไม่ขวางการแก้สิทธิ์ (EXCEPTION WHEN OTHERS THEN NULL) · สร้างจาก scratch generator · รันมือครั้งเดียวต่อสภาพแวดล้อม
CREATE TABLE IAMX.PERMISSION_AUDIT_LOG (
  ID          NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  TABLE_NAME  VARCHAR2(60 CHAR) NOT NULL,
  ACTION      VARCHAR2(10 CHAR) NOT NULL,
  ROW_KEY     VARCHAR2(100 CHAR),
  OLD_VALUE   CLOB,
  NEW_VALUE   CLOB,
  CHANGED_BY  VARCHAR2(200 CHAR),
  CHANGED_AT  TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL
)
/
CREATE INDEX IAMX.IX_PERM_AUDIT_TBL ON IAMX.PERMISSION_AUDIT_LOG (TABLE_NAME, CHANGED_AT)
/
CREATE INDEX IAMX.IX_PERM_AUDIT_AT ON IAMX.PERMISSION_AUDIT_LOG (CHANGED_AT)
/
CREATE OR REPLACE TRIGGER IAMX.TRG_AUDIT_ROLE
AFTER INSERT OR UPDATE OR DELETE ON IAMX.ROLE
FOR EACH ROW
DECLARE
  l_old CLOB; l_new CLOB; l_act VARCHAR2(10);
BEGIN
  l_act := CASE WHEN INSERTING THEN 'INSERT' WHEN UPDATING THEN 'UPDATE' ELSE 'DELETE' END;
  IF NOT INSERTING THEN SELECT JSON_OBJECT('CODE' VALUE :OLD.CODE, 'NAME' VALUE :OLD.NAME, 'DESCRIPTION' VALUE :OLD.DESCRIPTION, 'DEFAULT_ROLE' VALUE :OLD.DEFAULT_ROLE, 'EFFECTIVE_DATE' VALUE :OLD.EFFECTIVE_DATE, 'EXPIRE_DATE' VALUE :OLD.EXPIRE_DATE, 'IS_ACTIVE' VALUE :OLD.IS_ACTIVE, 'CREATED_BY' VALUE :OLD.CREATED_BY, 'UPDATED_BY' VALUE :OLD.UPDATED_BY, 'CREATED_AT' VALUE :OLD.CREATED_AT, 'UPDATED_AT' VALUE :OLD.UPDATED_AT, 'ALL_DATA_ACCESS' VALUE :OLD.ALL_DATA_ACCESS, 'ROLE_TYPE' VALUE :OLD.ROLE_TYPE, 'ID_OLD' VALUE :OLD.ID_OLD, 'ID' VALUE :OLD.ID ABSENT ON NULL RETURNING CLOB) INTO l_old FROM DUAL; END IF;
  IF NOT DELETING THEN SELECT JSON_OBJECT('CODE' VALUE :NEW.CODE, 'NAME' VALUE :NEW.NAME, 'DESCRIPTION' VALUE :NEW.DESCRIPTION, 'DEFAULT_ROLE' VALUE :NEW.DEFAULT_ROLE, 'EFFECTIVE_DATE' VALUE :NEW.EFFECTIVE_DATE, 'EXPIRE_DATE' VALUE :NEW.EXPIRE_DATE, 'IS_ACTIVE' VALUE :NEW.IS_ACTIVE, 'CREATED_BY' VALUE :NEW.CREATED_BY, 'UPDATED_BY' VALUE :NEW.UPDATED_BY, 'CREATED_AT' VALUE :NEW.CREATED_AT, 'UPDATED_AT' VALUE :NEW.UPDATED_AT, 'ALL_DATA_ACCESS' VALUE :NEW.ALL_DATA_ACCESS, 'ROLE_TYPE' VALUE :NEW.ROLE_TYPE, 'ID_OLD' VALUE :NEW.ID_OLD, 'ID' VALUE :NEW.ID ABSENT ON NULL RETURNING CLOB) INTO l_new FROM DUAL; END IF;
  IF UPDATING AND DBMS_LOB.COMPARE(l_old, l_new) = 0 THEN RETURN; END IF;
  INSERT INTO IAMX.PERMISSION_AUDIT_LOG (TABLE_NAME, ACTION, ROW_KEY, OLD_VALUE, NEW_VALUE, CHANGED_BY)
  VALUES ('ROLE', l_act,
          TO_CHAR(NVL(:NEW.ID, :OLD.ID)), l_old, l_new,
          SUBSTR(NVL(SYS_CONTEXT('USERENV','CLIENT_IDENTIFIER'), SYS_CONTEXT('USERENV','SESSION_USER'))
                 || ' / ' || SYS_CONTEXT('USERENV','MODULE'), 1, 200));
EXCEPTION WHEN OTHERS THEN NULL;  -- audit ห้ามขวางการแก้สิทธิ์
END;
/
